// - Hybrid algorithms (introsort, timsort-like)
// - Adaptive pivot selection
// - Special handling for nearly sorted data
// - Switching to different algorithms based on data characteristics

const INSERTION_THRESHOLD: usize = 24;

pub fn adaptive_sort<T: Ord>(arr: &mut [T]) {
    let len = arr.len();
    if len <= 1 { return; }
    if len <= INSERTION_THRESHOLD { insertion_sort(arr); return; }
    let max_depth = (2.0 * (len as f64).log2()) as usize;
    introsort(arr, 0, len - 1, max_depth);
}

fn introsort<T: Ord>(arr: &mut [T], low: usize, high: usize, depth: usize) {
    if high <= low { return; }
    let size = high - low + 1;
    if size <= INSERTION_THRESHOLD { insertion_sort(&mut arr[low..=high]); return; }
    if depth == 0 { heapsort(&mut arr[low..=high]); return; }

    // Hoare partition: returns j such that [low..=j] <= [j+1..=high]
    let j = partition_hoare(arr, low, high);
    if j > low { introsort(arr, low, j, depth - 1); }
    introsort(arr, j + 1, high, depth - 1);
}

fn median_of_three<T: Ord>(arr: &mut [T], low: usize, high: usize) {
    let mid = low + (high - low) / 2;
    if arr[mid] < arr[low] { arr.swap(low, mid); }
    if arr[high] < arr[low] { arr.swap(low, high); }
    if arr[high] < arr[mid] { arr.swap(mid, high); }
    // Use median as pivot at low
    arr.swap(low, mid);
}

fn partition_hoare<T: Ord>(arr: &mut [T], low: usize, high: usize) -> usize {
    if high - low >= 2 { median_of_three(arr, low, high); }
    let mut i = low;
    let mut j = high;
    loop {
        while arr[i] < arr[low] { i += 1; }
        while arr[j] > arr[low] { j -= 1; }
        if i >= j { return j; }
        arr.swap(i, j);
        i += 1;
        if j == 0 { return 0; } // avoid usize underflow
        j -= 1;
    }
}

fn heapsort<T: Ord>(arr: &mut [T]) {
    let n = arr.len();
    for i in (0..n / 2).rev() {
        sift_down(arr, i, n);
    }
    for i in (1..n).rev() {
        arr.swap(0, i);
        sift_down(arr, 0, i);
    }
}

fn sift_down<T: Ord>(arr: &mut [T], mut root: usize, end: usize) {
    loop {
        let child = 2 * root + 1;
        if child >= end { break; }
        let swap = if child + 1 < end && arr[child] < arr[child + 1] { child + 1 } else { child };
        if arr[root] >= arr[swap] { break; }
        arr.swap(root, swap);
        root = swap;
    }
}

fn insertion_sort<T: Ord>(arr: &mut [T]) {
    for i in 1..arr.len() {
        let mut j = i;
        while j > 0 && arr[j - 1] > arr[j] {
            arr.swap(j, j - 1);
            j -= 1;
        }
    }
